def find_regions(g,bg=3,fg=None):
    fg = fg or (lambda v: v!=bg)
    pts=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if fg(v)]
    # cluster by row bands (rows separated by empty rows)
    rows=sorted({p[0] for p in pts})
    bands=[]; cur=[rows[0]]
    for r in rows[1:]:
        if r==cur[-1]+1: cur.append(r)
        else: bands.append(cur); cur=[r]
    bands.append(cur)
    return bands

