lib='''\
def color_cells(grid, bg=0):
    """All cells whose color is not the background, as a list of (row, col, color)."""
    return [(i, j, v) for i, row in enumerate(grid) for j, v in enumerate(row) if v != bg]

def row_bands(grid, bg=0):
    """Row bands (lists of consecutive row indices) that contain non-background cells, top to bottom."""
    rows = sorted({i for i, _, _ in color_cells(grid, bg)})
    bands, cur = [], []
    for r in rows:
        if cur and r != cur[-1] + 1:
            bands.append(cur); cur = []
        cur.append(r)
    if cur: bands.append(cur)
    return bands

def best_xshift(grid, top, bottom, bg=0):
    """The horizontal shift dc that best aligns the shape in band `top` onto band `bottom` (same row offset)."""
    dr = bottom[0] - top[0]
    H, W = len(grid), len(grid[0])
    best = None
    for dc in range(-W, W + 1):
        ov = diff = 0
        for i, j, v in color_cells(grid, bg):
            if i in top and 0 <= i + dr < H and 0 <= j + dc < W:
                w = grid[i + dr][j + dc]
                if w != bg: ov += 1
                if w != v: diff += 1
        if best is None or (-ov, diff) < best[0]: best = ((-ov, diff), dc)
    return best[1]

def restore_copy(grid, bg=0, fill=1):
    """Two copies of one shape in two row bands: paint every cell of either copy that is background in the other with `fill`."""
    bands = row_bands(grid, bg)
    if len(bands) != 2: return grid
    top, bottom = bands
    dr = bottom[0] - top[0]
    dc = best_xshift(grid, top, bottom, bg)
    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for band, s in ((top, 1), (bottom, -1)):
        for i, j, v in color_cells(grid, bg):
            if i in band:
                i2, j2 = i + s * dr, j + s * dc
                if 0 <= i2 < H and 0 <= j2 < W and out[i2][j2] == bg:
                    out[i2][j2] = fill
    return out
'''
